147	    @Override
148	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
154	    }
155	
156	    /**
157	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
158	     * upper-cases the value, and expands common street-type abbreviations word-by-word
159	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
160	     * normalizes to the empty string. The normalized value is what the application stores, returns
161	     * and compares for household detection.
162	     *
163	     * @param address the raw address value from the request, may be {@code null}
164	     * @return the normalized address, or the empty string when none was supplied
165	     */
166	    private String normalizeAddress(String address) {
167	        if (address == null) {
168	            return "";
169	        }
170	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
171	        if (collapsed.isEmpty()) {
172	            return "";
173	        }
174	        String[] tokens = collapsed.split(" ");
175	        StringBuilder normalized = new StringBuilder();
176	        for (int i = 0; i < tokens.length; i++) {
177	            if (i > 0) {
178	                normalized.append(' ');
179	            }
180	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
181	        }
182	        return normalized.toString();
183	    }
184	
185	    /**
186	     * Rejects an owner payload that is missing or blank in any required field. The response body's
187	     * {@code errors} array lists the name of each offending field.
188	     *
189	     * @param ownerFieldsDto the owner payload to validate
190	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
191	     */
192	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
193	        List<String> missingFields = new ArrayList<>();
194	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
195	            missingFields.add("firstName");
196	        }
197	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
198	            missingFields.add("lastName");
199	        }
200	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
201	            missingFields.add("address");
202	        }
203	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
204	            missingFields.add("city");
205	        }
206	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
207	            missingFields.add("telephone");
208	        }
209	        if (!missingFields.isEmpty()) {
210	            throw new RequiredFieldsMissingException(missingFields);
211	        }
212	    }
213	
214	    /**
215	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
216	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
217	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
218	     * followed by 8 to 15 digits.
219	     *
220	     * @param telephone the raw telephone value from the request
221	     * @return the E.164 telephone (e.g. {@code +61412345678})
222	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
223	     */
224	    private String normalizeTelephone(String telephone) {
225	        if (telephone == null) {
226	            throw new InvalidFieldsException(List.of("telephone"));
227	        }
228	        String trimmed = telephone.trim();
229	        boolean international = trimmed.startsWith("+");
230	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
231	        String digits;
232	        if (international) {
233	            digits = cleaned.substring(1);
234	        } else {
235	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
236	            digits = "61" + national;
237	        }
238	        if (!digits.matches("[0-9]{8,15}")) {
239	            throw new InvalidFieldsException(List.of("telephone"));
240	        }
241	        return "+" + digits;
242	    }
243	
244	    /**
245	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
246	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
247	     *
248	     * @param telephone an existing stored telephone value, may be {@code null}
249	     * @return the E.164 form, or {@code null} when it cannot be normalized
250	     */
251	    private String toE164OrNull(String telephone) {
252	        if (telephone == null) {
253	            return null;
254	        }
255	        try {
256	            return normalizeTelephone(telephone);
257	        }
258	        catch (InvalidFieldsException ex) {
259	            return null;
260	        }
261	    }
262	
263	    /**
264	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
265	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
266	     * be a syntactically valid address; the accepted value is returned lower-cased.
267	     *
268	     * @param email the raw email value from the request, may be {@code null}
269	     * @return the lower-cased email, or {@code null} when none was supplied
270	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
271	     */
272	    private String normalizeEmail(String email) {
273	        if (email == null || email.isBlank()) {
274	            return null;
275	        }
276	        String trimmed = email.trim();
277	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
278	            throw new InvalidFieldsException(List.of("email"));
279	        }
280	        return trimmed.toLowerCase(Locale.ROOT);
281	    }
282	
283	    /**
284	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
285	     * owners' telephones are normalized the same way before comparison so differently-formatted
286	     * values representing the same number are treated as duplicates.
287	     *
288	     * @param telephone the normalized (E.164) telephone of the owner being created
289	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
290	     */
291	    private void requireUniqueTelephone(String telephone) {
292	        boolean taken = this.clinicService.findAllOwners().stream()
293	            .map(Owner::getTelephone)
294	            .map(this::toE164OrNull)
295	            .filter(existing -> existing != null)
296	            .anyMatch(telephone::equals);
297	        if (taken) {
298	            throw new DuplicateOwnerTelephoneException(telephone);
299	        }
300	    }
301	
302	    /**
303	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
304	     * fields (last name, address) can be compared case-insensitively with collapsed whitespace. A
305	     * {@code null} value normalizes to the empty string.
306	     *
307	     * @param value the raw field value, may be {@code null}
308	     * @return the trimmed, whitespace-collapsed, lower-cased form
309	     */
310	    private String normalizeHousehold(String value) {
311	        if (value == null) {
312	            return "";
313	        }
314	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
315	    }
316	
317	    /**
318	     * Rejects an owner whose last name and address already match another owner (compared
319	     * case-insensitively with collapsed whitespace) - i.e. they would share a household - unless the
320	     * request opts in via {@code sharesHousehold}. Existing owners' fields are normalized the same
321	     * way before comparison.
322	     *
323	     * @param lastName the last name of the owner being created
324	     * @param address the address of the owner being created
325	     * @throws DuplicateOwnerHouseholdException if another owner shares the household
326	     */
327	    private void requireUniqueHousehold(String lastName, String address) {
328	        String normalizedLastName = normalizeHousehold(lastName);
329	        String normalizedAddress = normalizeHousehold(address);
330	        boolean shared = this.clinicService.findAllOwners().stream()
331	            .anyMatch(existing -> normalizeHousehold(existing.getLastName()).equals(normalizedLastName)
332	                && normalizeHousehold(existing.getAddress()).equals(normalizedAddress));
333	        if (shared) {
334	            throw new DuplicateOwnerHouseholdException(lastName, address);
335	        }
336	    }
337	
338	    /**
339	     * Rejects an owner whose city already contains the maximum permitted number of owners
340	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
341	     * the same normalization used for the other owner household fields.
342	     *
343	     * @param city the city of the owner being created
344	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
345	     */
346	    private void requireCityHasCapacity(String city) {
347	        String normalizedCity = normalizeHousehold(city);
348	        long count = this.clinicService.findAllOwners().stream()
349	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
350	            .count();
351	        if (count >= CITY_CAPACITY) {
352	            throw new CityAtCapacityException(city);
353	        }
354	    }
355	
356	    /**
357	     * Rejects creating an owner once the given business day has already reached the maximum
358	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
359	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
360	     * registration date.
361	     *
362	     * @param registrationDate the business-day-adjusted registration date of the owner being created
363	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
364	     *     registered on that business day
365	     */
366	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
367	        long count = this.clinicService.findAllOwners().stream()
368	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
369	            .count();
370	        if (count >= DAILY_OWNER_LIMIT) {
371	            throw new DailyOwnerLimitException(registrationDate);
372	        }
373	    }
374	
375	    /**
376	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
377	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
378	     * been registered on that date. Evaluated before the new owner is persisted, so the count
379	     * reflects the owners that existed at the time of creation.
380	     *
381	     * @param registrationDate the business-day-adjusted registration date of the owner being created
382	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
383	     *     that registration date, otherwise {@code false}
384	     */
385	    private boolean isBulkSignup(LocalDate registrationDate) {
386	        long count = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
388	            .count();
389	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
390	    }
391	
392	    /**
393	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
394	     * following Monday, while a weekday is returned unchanged.
395	     *
396	     * @param date the effective registration date (supplied or defaulted to the server date)
397	     * @return the same date when it is a weekday, otherwise the next Monday
398	     */
399	    private LocalDate toBusinessDay(LocalDate date) {
400	        return switch (date.getDayOfWeek()) {
401	            case SATURDAY -> date.plusDays(2);
402	            case SUNDAY -> date.plusDays(1);
403	            default -> date;
404	        };
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Override
409	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
410	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
411	        validateRequiredFields(ownerFieldsDto);
412	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
413	        requireUniqueTelephone(telephone);
414	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
415	            requireUniqueHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
416	        }
417	        requireCityHasCapacity(ownerFieldsDto.getCity());
418	        String email = normalizeEmail(ownerFieldsDto.getEmail());
419	        HttpHeaders headers = new HttpHeaders();
420	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
421	        owner.setTelephone(telephone);
422	        owner.setEmail(email);
423	        LocalDate effectiveDate = owner.getRegistrationDate() != null
424	            ? owner.getRegistrationDate() : LocalDate.now();
425	        LocalDate registrationDate = toBusinessDay(effectiveDate);
426	        owner.setRegistrationDate(registrationDate);
427	        requireDailyLimitNotReached(registrationDate);
428	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
429	        this.clinicService.saveOwner(owner);
430	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
431	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
432	            ownerMapper.membershipLevel(owner));
433	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
434	        headers.setLocation(UriComponentsBuilder.newInstance()
435	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
436	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
437	    }
438	
439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Override
441	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
442	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
443	        if (currentOwner == null) {
444	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	        }
446	        currentOwner.setAddress(ownerFieldsDto.getAddress());
447	        currentOwner.setCity(ownerFieldsDto.getCity());
448	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
449	        currentOwner.setLastName(ownerFieldsDto.getLastName());
450	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
451	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
452	        this.clinicService.saveOwner(currentOwner);
453	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
454	    }
455	
456	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
457	    @Transactional
458	    @Override
459	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
460	        Owner owner = this.clinicService.findOwnerById(ownerId);
461	        if (owner == null) {
462	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
463	        }
464	        this.clinicService.deleteOwner(owner);
465	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
466	    }
467	
468	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
469	    @Override
470	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
471	        Owner owner = this.clinicService.findOwnerById(ownerId);
472	        if (owner == null) {
473	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
474	        }
475	        HttpHeaders headers = new HttpHeaders();
476	        Pet pet = petMapper.toPet(petFieldsDto);
477	        owner.setId(ownerId);
478	        pet.setOwner(owner);
479	        pet.getType().setName(null);
480	        this.clinicService.savePet(pet);
481	        PetDto petDto = petMapper.toPetDto(pet);
482	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
483	            .buildAndExpand(pet.getId()).toUri());
484	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
485	    }
486	
487	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
488	    @Override
489	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
490	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
491	        if (currentOwner != null) {
492	            Pet currentPet = this.clinicService.findPetById(petId);
493	            if (currentPet != null) {
494	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
495	                currentPet.setName(petFieldsDto.getName());
496	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
497	                this.clinicService.savePet(currentPet);
498	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
499	            }
500	        }
501	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
502	    }
503	
504	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
505	    @Override
506	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
507	        HttpHeaders headers = new HttpHeaders();
508	        Visit visit = visitMapper.toVisit(visitFieldsDto);
509	        Pet pet = new Pet();
510	        pet.setId(petId);
511	        visit.setPet(pet);
512	        this.clinicService.saveVisit(visit);
513	        VisitDto visitDto = visitMapper.toVisitDto(visit);
514	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
515	            .buildAndExpand(visit.getId()).toUri());
516	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
517	    }
518	
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
521	    @Override
522	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
523	        Owner owner = this.clinicService.findOwnerById(ownerId);
524	        if (owner != null) {
525	            Pet pet = owner.getPet(petId);
526	            if (pet != null) {
527	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
528	            }
529	        }
530	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
531	    }
532	}
