17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
58	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has reached its owner capacity";
59	    private static final String ERROR_DAILY_OWNER_LIMIT = "The daily owner registration limit has been reached";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
81	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
82	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
83	     * would catch it and report an authorization failure as a 500.
84	     *
85	     * @param e The {@link AccessDeniedException} to propagate
86	     * @throws AccessDeniedException always
87	     */
88	    @ExceptionHandler(AccessDeniedException.class)
89	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
90	        throw e;
91	    }
92	
93	    /**
94	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
95	     *
96	     * @param e The {@link Exception} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
99	     */
100	    @ExceptionHandler(Exception.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
103	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
104	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
106	        return ResponseEntity.status(status).body(detail);
107	    }
108	
109	    /**
110	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
111	     * method returns a 404 Not Found status if an entity does not exist.
112	     *
113	     * @param e The {@link DataIntegrityViolationException} to be handled
114	     * @param request {@link HttpServletRequest} object referring to the current request.
115	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
116	     */
117	    @ExceptionHandler(DataIntegrityViolationException.class)
118	    @ResponseBody
119	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
120	        logger.warn("Data integrity violation at {} {}: {}",
121	            request.getMethod(),
122	            request.getRequestURI(),
123	            e.getMessage());
124	        logger.debug("Data integrity violation stacktrace", e);
125	        HttpStatus status = HttpStatus.NOT_FOUND;
126	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
127	        return ResponseEntity.status(status).body(detail);
128	    }
129	
130	    /**
131	     * Handles exception thrown by Bean Validation on controller methods parameters
132	     *
133	     * @param e The {@link MethodArgumentNotValidException} to be handled
134	     * @param request {@link HttpServletRequest} object referring to the current request.
135	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
136	     */
137	    @ExceptionHandler(MethodArgumentNotValidException.class)
138	    @ResponseBody
139	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
140	        HttpStatus status = HttpStatus.BAD_REQUEST;
141	        BindingErrorsResponse errors = new BindingErrorsResponse();
142	        BindingResult bindingResult = e.getBindingResult();
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
144	        if (bindingResult.hasErrors()) {
145	            errors.addAllErrors(bindingResult);
146	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
147	                .map(FieldError::getField)
148	                .distinct()
149	                .toList();
150	            detail.setProperty("errors", invalidFields);
151	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
152	                .map(fieldError -> {
153	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
154	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
155	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
156	                        fieldError.getField(),
157	                        defaultMessage,
158	                        rejectedValue);
159	                    return new ValidationMessageDto(message)
160	                        .putAdditionalProperty("field", fieldError.getField())
161	                        .putAdditionalProperty("rejectedValue", rejectedValue)
162	                        .putAdditionalProperty("defaultMessage", defaultMessage);
163	                })
164	                .toList();
165	            logger.debug("Validation error at {} {}: {}",
166	                request.getMethod(),
167	                request.getRequestURI(),
168	                bindingResult.getFieldErrors());
169	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
170	            return ResponseEntity.status(status).body(detail);
171	        }
172	        return ResponseEntity.status(status).body(detail);
173	    }
174	
175	    /**
176	     * Handles {@link RequiredFieldsMissingException} raised when a request is missing or blank in
177	     * one or more required fields. Returns a 400 Bad Request whose body's {@code errors} array
178	     * lists the name of each offending field.
179	     *
180	     * @param e The {@link RequiredFieldsMissingException} to be handled
181	     * @param request {@link HttpServletRequest} object referring to the current request.
182	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
183	     */
184	    @ExceptionHandler(RequiredFieldsMissingException.class)
185	    @ResponseBody
186	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", e.getMissingFields());
190	        logger.debug("Missing required fields at {} {}: {}",
191	            request.getMethod(),
192	            request.getRequestURI(),
193	            e.getMissingFields());
194	        return ResponseEntity.status(status).body(detail);
195	    }
196	
197	    /**
198	     * Handles {@link InvalidFieldsException} raised when a request carries one or more fields
199	     * whose values are present but invalid. Returns a 400 Bad Request whose body's {@code errors}
200	     * array lists the name of each offending field.
201	     *
202	     * @param e The {@link InvalidFieldsException} to be handled
203	     * @param request {@link HttpServletRequest} object referring to the current request.
204	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
205	     */
206	    @ExceptionHandler(InvalidFieldsException.class)
207	    @ResponseBody
208	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
209	        HttpStatus status = HttpStatus.BAD_REQUEST;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
211	        detail.setProperty("errors", e.getInvalidFields());
212	        logger.debug("Invalid fields at {} {}: {}",
213	            request.getMethod(),
214	            request.getRequestURI(),
215	            e.getInvalidFields());
216	        return ResponseEntity.status(status).body(detail);
217	    }
218	
219	    /**
220	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner is created with a
221	     * normalized telephone that is already used by another owner. Returns a 409 Conflict whose
222	     * body's {@code errors} array names the offending {@code telephone} field.
223	     *
224	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
225	     * @param request {@link HttpServletRequest} object referring to the current request.
226	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
227	     */
228	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
229	    @ResponseBody
230	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
231	        HttpStatus status = HttpStatus.CONFLICT;
232	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
233	        detail.setProperty("errors", List.of("telephone"));
234	        logger.debug("Duplicate owner telephone at {} {}: {}",
235	            request.getMethod(),
236	            request.getRequestURI(),
237	            e.getTelephone());
238	        return ResponseEntity.status(status).body(detail);
239	    }
240	
241	    /**
242	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner is created whose last
243	     * name and address already match another owner (a shared household) without the request opting
244	     * in via the {@code sharesHousehold} flag. Returns a 409 Conflict whose body's {@code errors}
245	     * array names the offending {@code lastName} and {@code address} fields.
246	     *
247	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
248	     * @param request {@link HttpServletRequest} object referring to the current request.
249	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
250	     */
251	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
252	    @ResponseBody
253	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
